from save import *
save({
'A0955-B0002':'帷幕地区是太平星域内一片辽阔的未测绘区域，由稠密星云和新生恒星组成。这里笼罩着恒星尘埃，辐射波与恒星抛出的物质在其中涌动。已知居民包括众多绿皮海盗、一个生活在垂死世界上的迟缓原始种族，以及少量异形雇佣兵和商人。鲜有人知道，太空死灵也栖居于这片宙域。',
'A0955-B0004':'自帝国有历史记录以来，这片区域就被称为帷幕地区。自大远征时代起，探索舰队对当地星云的探查便始终浅尝辄止，因此帝国所知甚少。一名行商浪人在前往银河西缘之前，曾沿帷幕地区外围航行；其记录仅提到与少数异形种族的接触。在这里进行的少量航行，无一不险象环生。赫鲁尔等人认为，深入其中所需的庞大资源，是这片区域始终未被探索的原因。帝国法律禁止人类在帷幕地区建立殖民地，但有关当地存在人类定居点的传闻，虽然从未证实，却一直流传。这里最大的危险之一，就是与外界隔绝：星语通讯极为困难，灵能讯息会被反射回来，化作回声，却收不到任何答复。因此，深入探索的尝试极少，也从未取得成功。',
'A0955-B0006':'巴拉德林·塔尔曾得到一件考古科技造物。他声称，这是一名叫德维安的行商浪人从帷幕地区带回的。机械修会无法查明造物的来历，只能确定它出自一个技术高度发达的异形文明，于是派大贤者沃亚尔前往帷幕地区追查。沃亚尔组建探索舰队，寻找这副神秘面具的异形制造者。舰队从火星舰队抽调而来，由旗舰对立号率领；沃亚尔认为，其兵力足以轻松完成远征。由于面具呈人脸形状，机械修会推测帷幕地区可能存在人类定居点，或受异形统治，或与异形结盟。因此，沃亚尔还奉命解放这些居民，将他们纳入人类帝国。远征进入第二年，探索舰队穿过延绵数光年、愈发浓密的星云与恒星云团，终于突破帷幕，驶入清朗的虚空。',
'A0955-B0008':'同一时期，被帝国宣布为叛徒的饮魂者战团，乘太空废船断背号进入帷幕地区以躲避追捕；帝国已有数千年未曾探索此地。为了摆脱机械修会，他们不断深入，直到战团长萨尔佩冬获知，舰船已经进入未探索的宙域。当地太空死灵此时从长眠中苏醒，迫使机械修会与饮魂者以及当地人类居民结盟，共同对抗这一威胁。',
'A0955-B0010':'帷幕地区也是银河中众多遭吞世者叛徒军团严重蹂躏的区域之一。',
'A0956-B0002':'“带我离开故乡，我便驶向您帝国的群星。我将尽一个儿子应尽的职责，侍奉于您。但请让科尔基斯保有我塑造的模样：一个和平而繁荣的世界。”',
'A0956-B0004':'——据称出自珞珈之口，铭刻于通往圣约螺旋的大门金匾上',
'A0956-B0015':'类别：死寂世界，于035.M31毁灭',
'A0956-B0019':'科尔基斯曾是怀言者星际战士军团最初的母星。荷鲁斯之乱后，它在轨道轰炸下被迫屈服，又因独特的地质构造而整体碎裂、爆炸。其所在位置成为审判庭严守的秘密。',
'A0956-B0022':'科尔基斯体型庞大，约为泰拉的三倍。它绕恒星公转一周需4.8个泰拉年，自转一周则需170.4个泰拉小时。如此漫长的昼夜周期令人类难以适应，因此当地文明发展出独特的计时方式：将一个太阳日分为七个子日，依次称为拂远、上午、长午、午后、昏前、冷落和至夜。每个子日又分为醒起、醒主和休前三个时段，以便更贴近泰拉人的日常作息。一日中最热的是长午的醒主时段，最冷的是至夜的休前时段。',
'A0956-B0024':'科尔基斯陆地多为山脉与沙漠，聚落集中在海岸，彼此依靠水路和空中交通往来。首都城邦为维拉德什，亦称灰花之城。',
'A0956-B0026':'科尔基斯的城市全部由名为“圣约”的宗教组织控制，而城外的生活通常十分艰苦。奴隶制盛行，住在城外的沙漠游牧民被称为“衰落者”，被视为遭到至高诸神诅咒的人。',
'A0956-B0029':'科尔基斯原本技术发达，但在珞珈到来前已经退化为封建社会。地表散布古老遗迹，轨道上漂浮着废弃星舰。珞珈降临时，星球由科尔基斯圣约统治。科尔·法伦将他抚养成人，后来珞珈领导叛乱，推翻圣约并征服了整个星球。',
'A0956-B0031':'帝皇找到珞珈后，他将科尔基斯带入帝国，使当地得以接触先进技术和社会制度。在珞珈短暂的统治期间，星球欣欣向荣；然而帝皇带走他后，这里又迅速退回封建社会。帝国舰船通常避开科尔基斯，既因为这里缺乏轨道设施，也因为第2188远征舰队失踪后，传言称这一带并不安全。',
'A0956-B0033':'从010.M31起，科尔基斯在荷鲁斯之乱的苦难战争中遭受多次帝国进攻。战后极限战士重返此地执行净化时，所见已是一个全面崩溃的世界：工业尽数毁坏，居民挣扎求生。审判庭下令使用旋风鱼雷清洗星球，结果破坏了科尔基斯脆弱的地质结构，引发灾难性爆炸，将整颗行星彻底毁灭。此时，考斯战事计时已达到219,479.25.03，约合二十五年。',
'A0956-B0038':'科尔基斯戴环者太阳辅助军诸团的兵员，征自科尔基斯。',
'A0957-B0011':'哈拉孔是一颗重力较低的巢都世界，巢都尖塔直耸高层大气。',
'A0957-B0013':'哈拉孔人口众多，为帝国卫队组建了大批军团，统称哈拉考尼战鹰。尖塔下方是群山间的隘道，当地人驾着重力滑翔机，在其中猎捕本土生物雾龙。',
'A0958-B0013':'海德拉弗是一颗铸造世界，也是太平星域的行政首府与舰队总部所在地。',
'A0958-B0016':'海德拉弗轨道上有庞大的升腾星堡，以及环绕星球的巨型造船厂。这些人造环虽然不及月球或火星的环形设施庞大，却承担着太平星域舰队基地的职能。星球本身分属数方势力：帝国海军掌控大气层及其上方空间，地表则由国教和机械修会在紧张的合作关系中共同统治。',
'A0958-B0019':'无信瘟疫期间，海德拉弗向红衣主教布查里斯的叛军投降，令后世几代人蒙羞。星球重归帝国后，红衣主教蔡·巴尔罗纳斯设立了以斋戒和忏悔仪式为核心的年度宗教节庆。此事的另一个后果，是内政部试图削弱帝国海军在该星系的权力。海德拉弗星系虽是舰队行动中枢，国教与审判庭的行政力量仍被加强，拥有当地地产的海军家族则逐步失去财产。不过，分权改革的成效好坏参半：海德拉弗本土虽由内政部与国教主导，海军却反过来收紧了对星系其他地区及整个次星区的控制，甚至迫使当地国教必须派遣秘密信使，才能与其他星系的同僚通讯。海军还与当地商人家族建立密切关系，双方商业联盟的纽带几乎被视为家族关系。叛教时代的冲突过后，在巴尔罗纳斯主持的改革下，海德拉弗最终由海军、国教和机械教分掌。',
'A0958-B0021':'大裂隙形成后，黑色军团入侵海德拉弗，帝国派兵保卫星球。然而，黑色军团凭借庞大兵力持续推进，迫使除禁军之外的守军后撤。无论敌人发动多少次冲锋，禁军都岿然不动，以耀金铸成的防线击碎叛徒攻势。到不屈远征初期，海德拉弗已遭混沌军队进攻三次。'
},[955,956,957,958],{'A0955-B0004':'“从未成功”是该背景段的概述；下文记有突破星云、发现居民的具体远征，原文叙述口径差异保留。','A0955-B0006':'修正 except that 的限定关系：只能确认异形来源，并非“除非来自异形文明”。面具呈人脸形状，不能直接推出制造者就是人类，正文保留机械修会的推测口吻。','A0956-B0022':'seven sub-days 与170.4小时保留原数值；最热时段原文为 wake-main，原译误作 wake-rise，已改回醒主。three times larger 按上下文约三倍表达，不据歧义增算为四倍。','A0956-B0026':'Great Powers 此处为科尔基斯宗教中的神明，不是地缘政治“列强”；被诅咒的对象是游牧民。','A0958-B0019':'同篇前段用 Adeptus Mechanicus，此历史段末尾却用 Mechanicum；分别保留机械修会／机械教，并标原文名称跨时代使用疑点，不暗改英文。'})
with (P/'terms.tsv').open('a') as f:
 for en,zh,loc,n in [('Khrul','赫鲁尔','955','人物'),('Baradrin Thaal','巴拉德林·塔尔','955','造物持有者'),('Devian','德维安','955','行商浪人'),('Archmagos Voar','大贤者沃亚尔','955','探索舰队指挥者'),('Antithesis','对立号','955','旗舰'),('Brokenback','断背号','955','饮魂者废船'),('Spiral of the Covenant','圣约螺旋','956','建筑地点'),('Colchisian Torquatii','科尔基斯戴环者','956','太阳辅助军部队'),('Vapourwyrms','雾龙','957','本土生物'),('Konndar','康达尔','957','当地主要方言'),('Ascendant','升腾星堡','958','轨道星堡，区别同名人物称号'),('Chye Balronas','蔡·巴尔罗纳斯','958','红衣主教')]:f.write('\t'.join([en,zh,'暂定·官方待核','所给英文底稿',loc,n])+'\n')
